window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[218]={"id":"218","numero":218,"titre":"Éosinophilie","objectifs":[{"id":"218-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’éosinophilie","contenu":"<p>L'<span class=\"kw-def\">éosinophilie</span> désigne une augmentation du nombre de <span class=\"kw-def\">polynucléaires éosinophiles</span> (PNE) circulants, constatée sur <strong>plusieurs <span class=\"kw-bio\">NFS</span> successives</strong> — le caractère <strong>persistant</strong> est essentiel au diagnostic.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Seuil (valeur absolue)</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Éosinophilie modérée</span></td><td><span class=\"kw-chiffre\">0,5 – 1,5 G/L</span> selon la médecine interne ; <span class=\"kw-chiffre\">0,5 – 1 G/L</span> selon l'hématologie</td></tr>\n          <tr><td><span class=\"kw-def\">Hyperéosinophilie</span></td><td><span class=\"kw-chiffre\">&gt; 1,5 G/L</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le diagnostic repose sur la <strong>valeur absolue</strong> des PNE : le <span class=\"kw-bio\">pourcentage de PNE</span> dans la formule leucocytaire n'a <em>aucune utilité</em>.</div>\n      <p><strong>Rappel sur le PNE.</strong> L'éosinophilopoïèse (CSH → progéniteurs granuleux → PNE) dépend surtout de l'<span class=\"kw-bio\">IL-5</span> (accessoirement IL-3 et GM-CSF), qui assure production, <span class=\"kw-bio\">différenciation</span> et passage médullo-sanguin. Le PNE ne fait qu'un <strong>séjour bref dans le sang</strong> puis gagne rapidement <span class=\"kw-clinique\">les</span> tissus et muqueuses (<span class=\"kw-clinique\">cutanée</span>, <span class=\"kw-clinique\">digestive</span>, <span class=\"kw-clinique\">pulmonaire</span>, <span class=\"kw-clinique\">urogénitale</span>) sous l'effet de facteurs chimiotactiques. Son cytoplasme contient de volumineuses <span class=\"kw-bio\">granulations rose-orangé</span> riches en molécules pro-inflammatoires.</p>","frequence":2},{"id":"218-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le rôle délétère de l’excès d’éosinophiles","contenu":"<p>Le PNE libère de nombreux <span class=\"kw-bio\">médiateurs inflammatoires</span> — <span class=\"kw-bio\">protéines cationiques</span>, <span class=\"kw-bio\">cytokines</span>, <span class=\"kw-bio\">radicaux oxygénés</span> — dont l'action est à <strong>double tranchant</strong>.</p>\n      <table >\n        <thead><tr><th>Rôle</th><th>Effets</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Bénéfique</strong></td><td>Altération / destruction des <span class=\"kw-etio\">larves de parasites</span>, des <span class=\"kw-etio\">virus</span> et des <span class=\"kw-etio\">cellules tumorales</span> ; neutralisation des réactions d'<span class=\"kw-def\">hypersensibilité immédiate</span> (<span class=\"kw-ci\">allergie</span>) par libération d'<span class=\"kw-bio\">histaminase</span></td></tr>\n          <tr><td><strong>Délétère</strong></td><td>Médiateurs <span class=\"kw-alerte\">cytotoxiques</span> et <span class=\"kw-alerte\">prothrombotiques</span> ; <span class=\"kw-clinique\">les</span> tissus infiltrés par les PNE subissent des lésions potentiellement graves — atteinte <span class=\"kw-alerte\">cardiaque</span> et <span class=\"kw-alerte\">thromboses vasculaires</span> au premier plan</td></tr>\n        </tbody>\n      </table>\n      <p>C'est ce rôle délétère qui fait toute la gravité d'une <span class=\"kw-alerte\">éosinophilie chronique</span> : <span class=\"kw-clinique\">les</span> dégâts tissulaires sont liés à l'<span class=\"kw-alerte\">infiltration tissulaire</span> par les PNE, et non au <span class=\"kw-bio\">chiffre sanguin</span> (cf. <span class=\"kw-alerte\">retentissement viscéral</span>, obj-7).</p>","frequence":0},{"id":"218-3","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir que parmi les parasitoses ce sont essentiellement les helminthoses qui en sont responsables","contenu":"<p>Devant une éosinophilie, <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">parasitoses</span> sont une cause majeure — mais toutes ne sont pas en cause. Ce sont essentiellement les <span class=\"kw-def\">helminthoses</span> (vers) qui s'accompagnent d'une éosinophilie ; les protozooses en sont quasiment dépourvues.</p>\n      <div class=\"callout callout-info\"><strong>À retenir — mnémo PLAT.</strong> <span class=\"kw-clinique\">Les</span> 4 parasitoses <strong>sans</strong> éosinophilie : <span class=\"kw-etio\">P</span>aludisme ; <span class=\"kw-etio\">L</span>eishmaniose ; <span class=\"kw-etio\">A</span>mibiase ; <span class=\"kw-etio\">T</span>rypanosomiase. <em>Toutes les autres</em> parasitoses — c'est-à-dire les helminthoses — donnent une éosinophilie.</div>\n      <p><strong>Démarche diagnostique d'une helminthose.</strong> <span class=\"kw-clinique\">Les</span> examens complémentaires sont guidés par l'<span class=\"kw-clinique\">interrogatoire</span> et la <span class=\"kw-clinique\">clinique</span> (notion de voyage notamment).</p>\n      <ul>\n        <li><strong><span class=\"kw-bio\">Sérologies</span> parasitaires :</strong> analyses <span class=\"kw-clinique\">les</span> <strong>plus contributives</strong>, applicables à un grand nombre d'helminthes.</li>\n        <li><strong>Diagnostic direct :</strong> <span class=\"kw-bio\">examen parasitologique des selles</span> (œufs : ascaridiose, distomatose, bilharziose sauf <em>S. haematobium</em>) ; <span class=\"kw-bio\">examen parasitologique des urines</span> (bilharziose à <em>Schistosoma haematobium</em>) ; <span class=\"kw-bio\">frottis sanguin</span> (parasites sanguicoles — filarioses).</li>\n        <li><strong>Autres :</strong> électrophorèse parasitologique des selles avec techniques de concentration si suspicion de <span class=\"kw-etio\">strongyloïdose</span> ; <span class=\"kw-bio\">imagerie</span> (toxocarose, distomatose) ; <span class=\"kw-bio\">biopsie musculaire</span> (trichinellose).</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Traitement d'épreuve.</strong> Envisageable si l'enquête parasitologique n'est pas concluante : <span class=\"kw-ttt\">albendazole</span> ou <span class=\"kw-ttt\">flubendazole</span>, avec <span class=\"kw-def\">suivi</span> du taux de PNE.</div>\n      <div class=\"callout callout-danger\"><strong>Piège majeur.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-ci\">corticoïdes sont formellement contre-indiqués</span> dans une hyperéosinophilie secondaire à une helminthose : risque d'<span class=\"kw-alerte\">hyperinfestation parasitaire</span> (anguillulose maligne par auto-réinfestation digestive).</div>","frequence":0},{"id":"218-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître et savoir identifier les causes classiques d’éosinophilie (atopie, parasitoses, iatrogènes, cancer)","contenu":"<p>Face à toute éosinophilie, <strong>quatre causes classiques</strong> doivent être évoquées systématiquement — mnémo <span class=\"kw-def\">A·P·I·C</span>. C'est l'objectif le plus tombé de l'item à l'EDN.</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Éléments d'orientation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A — Atopie</strong></td><td><span class=\"kw-def\">Terrain</span> <span class=\"kw-etio\">atopique</span> : <span class=\"kw-clinique\">asthme</span>, <span class=\"kw-clinique\">rhinite</span>, <span class=\"kw-clinique\">dermatite atopique</span>, <span class=\"kw-clinique\">urticaire</span> ; éosinophilie modérée <span class=\"kw-chiffre\">&lt; 1 G/L</span>, variable dans le temps</td></tr>\n          <tr><td><strong>P — Parasitoses</strong></td><td>Essentiellement <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">helminthoses</span> ; à rechercher selon la notion de <span class=\"kw-clinique\">voyage</span> en zone tropicale (cf. obj-10, obj-11, obj-13)</td></tr>\n          <tr><td><strong>I — <span class=\"kw-etio\">Iatrogène</span></strong></td><td>Cause <span class=\"kw-ttt\">médicamenteuse</span> à évoquer systématiquement ; <strong>lien temporel</strong> avec l'introduction du traitement ; du <span class=\"kw-clinique\">rash</span> isolé au <span class=\"kw-alerte\">DRESS</span></td></tr>\n          <tr><td><strong>C — Cancer</strong></td><td><span class=\"kw-etio\">Hémopathies</span> (lymphomes, leucémies) et <span class=\"kw-etio\">cancers solides</span> ; production <span class=\"kw-etio\">paranéoplasique</span> d'<span class=\"kw-bio\">IL-5</span></td></tr>\n        </tbody>\n      </table>\n      <p>La fiche regroupe également ces causes en <strong>trois grands cadres</strong> : <span class=\"kw-def\">hypersensibilité</span>, <span class=\"kw-def\">parasitoses</span> et causes <span class=\"kw-def\">néoplasiques</span>.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-clinique\">Les</span> trois causes <strong>les plus fréquentes</strong> d'hyperéosinophilie sont les <span class=\"kw-clinique\">dermatoses prurigineuses</span>, les <span class=\"kw-etio\">helminthiases</span> et les <span class=\"kw-def\">allergies</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 186 — <span class=\"kw-ci\">Hypersensibilité</span> - allergie · 319 — Lymphome malin · 325 — Gestions des risques liés aux médicaments (<span class=\"kw-etio\">iatrogène</span>, erreur)</em></p>","frequence":8},{"id":"218-5","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir évoquer le diagnostic d’éosinophilie clonale","contenu":"<p>L'<span class=\"kw-def\">éosinophilie clonale</span> (synonymes : <span class=\"kw-def\">hyperéosinophilie non réactionnelle</span>, <span class=\"kw-def\">SHE myéloïde</span>) correspond à une <span class=\"kw-def\">anomalie clonale de la lignée éosinophile</span> au niveau de la <span class=\"kw-bio\">moelle osseuse</span> : <span class=\"kw-clinique\">les</span> PNE sont alors <span class=\"kw-def\">myéloprolifératifs</span>, et non réactionnels à une cause externe.</p>\n      <p>Trois ordres d'arguments font évoquer le caractère clonal :</p>\n      <table >\n        <thead><tr><th>Argument</th><th>Élément</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Clinique</strong></td><td><span class=\"kw-clinique\">Splénomégalie</span> sans cause retrouvée</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Biologique</span></strong></td><td>Élévation de la <span class=\"kw-bio\">vitamine B12</span> et/ou de la <span class=\"kw-bio\">tryptase sérique</span></td></tr>\n          <tr><td><strong>Thérapeutique</strong></td><td><span class=\"kw-alerte\">Cortico-résistance</span></td></tr>\n        </tbody>\n      </table>\n      <p>Ce diagnostic s'inscrit dans le cadre des <span class=\"kw-def\">syndromes hyperéosinophiliques</span> primitifs (cf. obj-6) et impose un <span class=\"kw-ttt\">avis hématologique spécialisé</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 317 — Syndrome myéloprolifératif</em></p>","frequence":0},{"id":"218-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les pathologies à évoquer face à une éosinophilie dans un contexte d’asthme","contenu":"<p>Une éosinophilie survenant dans un <strong>contexte d'<span class=\"kw-def\">asthme</span></strong> doit faire évoquer quatre entités spécifiques.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Syndrome de Fernand Widal</span></td><td>Triade : prise d'<span class=\"kw-ttt\">aspirine ou d'AINS</span> + <span class=\"kw-clinique\">polypose naso-sinusienne</span> + <span class=\"kw-clinique\">asthme</span></td></tr>\n          <tr><td><span class=\"kw-def\">GEPA</span></td><td>Granulomatose éosinophilique avec polyangéite — <span class=\"kw-def\">vascularite</span> des petits vaisseaux (cf. item 193)</td></tr>\n          <tr><td><span class=\"kw-def\">ABPA</span></td><td>Aspergillose broncho-pulmonaire <span class=\"kw-etio\">allergique</span> : <span class=\"kw-ci\">hypersensibilité</span> de type I (<span class=\"kw-chiffre\">IgE</span> médiée) à <span class=\"kw-etio\">Aspergillus fumigatus</span>. <span class=\"kw-def\">Asthme</span> ancien, <span class=\"kw-clinique\">toux</span>, <span class=\"kw-clinique\">expectoration</span> de « moules bronchiques » (bouchons mycéliens) ; <span class=\"kw-bio\">IgE totales</span> très élevées + hyperéosinophilie massive ; <span class=\"kw-radio\">images radiologiques variées</span> ; <span class=\"kw-def\">critère majeur</span> = <span class=\"kw-bio\">IgE spécifiques anti-Aspergillus</span></td></tr>\n          <tr><td><span class=\"kw-def\">Syndrome de Loffler</span></td><td>Migration trans-pulmonaire de larves, d'origine <span class=\"kw-etio\">parasitaire</span> (<span class=\"kw-etio\">anguillulose</span>, <span class=\"kw-etio\">ascaridiose</span>) : signes respiratoires modestes et fugaces (<span class=\"kw-clinique\">toux</span>, <span class=\"kw-clinique\">dyspnée</span>), <span class=\"kw-radio\">infiltrats radiologiques labiles</span> souvent périphériques, parfois multiples et bilatéraux</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 188 — <span class=\"kw-def\">Asthme</span> - Rhinite · 193 — <span class=\"kw-def\">Vascularite</span> systémique</em></p>","frequence":0},{"id":"218-7","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir identifier un syndrome hyperéosinophilique","contenu":"<p>Le <span class=\"kw-def\">syndrome hyperéosinophilique</span> (SHE) regroupe <span class=\"kw-clinique\">les</span> hyperéosinophilies <strong>primitives</strong>. C'est un <strong>diagnostic d'exclusion</strong>, et il reste souvent inexpliqué.</p>\n      <div class=\"callout callout-info\"><strong>Définition.</strong> Hyperéosinophilie <span class=\"kw-chiffre\">&gt; 1500/mm³</span>, évoluant depuis <span class=\"kw-chiffre\">≥ 6 mois</span>, <strong>après avoir écarté toutes <span class=\"kw-clinique\">les</span> causes</strong> d'hyperéosinophilie.</div>\n      <table >\n        <thead><tr><th>Forme</th><th>Mécanisme &amp; arguments</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">SHE myéloïde</span></td><td>PNE clonaux / myéloprolifératifs (anomalie clonale médullaire). Arguments : <span class=\"kw-clinique\">splénomégalie</span> inexpliquée ; <span class=\"kw-bio\">vitamine B12</span> et/ou <span class=\"kw-bio\">tryptase</span> élevées ; <span class=\"kw-alerte\">cortico-résistance</span></td></tr>\n          <tr><td><span class=\"kw-def\">SHE lymphoïde</span></td><td>Clones lymphocytaires <strong>T</strong> produisant de l'<span class=\"kw-bio\">IL-5</span>. Arguments : <span class=\"kw-bio\">IgE totales</span> élevées ; <strong>bonne réponse</strong> à la <span class=\"kw-ttt\">corticothérapie</span></td></tr>\n          <tr><td><strong>Autres formes</strong></td><td>Leucémie chronique à <span class=\"kw-bio\">éosinophiles</span> (associée à une LMC <span class=\"kw-bio\">BCR-ABL</span>) ; SHE associé à une mastocytose systémique avec mutation de <span class=\"kw-bio\">c-KIT</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-def\">Pronostic</span>.</strong> Sombre en l'absence de traitement. L'<span class=\"kw-ttt\">imatinib</span> est le médicament de choix dans la plupart des SHE.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 317 — Syndrome myéloprolifératif</em></p>","frequence":1},{"id":"218-8","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux retentissements viscéraux d’une éosinophilie chronique","contenu":"<p>Une éosinophilie <strong>chronique</strong> expose à des atteintes d'organes liées à l'<strong><span class=\"kw-ttt\">infiltration</span> tissulaire</strong> par <span class=\"kw-clinique\">les</span> PNE.</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Fibrose endomyocardique / endocardite de Loffler</span> — tableau de cardiomyopathie restrictive, le plus souvent <strong>irréversible et fatale</strong>.</li>\n        <li><span class=\"kw-alerte\">Thromboses vasculaires</span> — artérielles ou veineuses.</li>\n        <li>Atteintes <span class=\"kw-clinique\">pulmonaires</span>, <span class=\"kw-clinique\">digestives</span> (colite à PNE, œsophagite à PNE), <span class=\"kw-clinique\">cutanées</span>, du <span class=\"kw-clinique\">SNC</span> ou du <span class=\"kw-clinique\">SNP</span> (neuropathie périphérique).</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Piège fondamental — pas de corrélation taux / atteinte.</strong> Une hyperéosinophilie <span class=\"kw-chiffre\">&gt; 100 G/L</span> peut être <strong>asymptomatique</strong>, tandis qu'une éosinophilie <span class=\"kw-chiffre\">&lt; 5 G/L</span> peut donner une atteinte cardiaque engageant le <span class=\"kw-alerte\">pronostic vital</span>. C'est la <strong>persistance</strong>, et non le chiffre, qui impose le bilan de retentissement.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span></em></p>","frequence":0},{"id":"218-9","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier les situations d’urgence en présence d’une éosinophilie","contenu":"<p>Deux registres définissent l'<span class=\"kw-alerte\">urgence</span> devant une éosinophilie : le <strong>retentissement viscéral</strong> et certaines <strong>étiologies graves</strong>.</p>\n      <table >\n        <thead><tr><th>Registre</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Retentissement viscéral de l'hyperéosinophilie</strong></td><td><span class=\"kw-alerte\">Défaillance respiratoire</span> ; <span class=\"kw-alerte\">défaillance cardiaque</span> ; <span class=\"kw-alerte\">défaillance neurologique</span> (parfois d'origine <span class=\"kw-alerte\">thrombotique artérielle</span>)</td></tr>\n          <tr><td><strong>Étiologies graves</strong></td><td><span class=\"kw-alerte\">Atteinte cardiaque</span> d'une <span class=\"kw-etio\">GEPA</span> ; <span class=\"kw-etio\">hémopathies malignes</span> ; <span class=\"kw-alerte\">anguillulose maligne</span> (<span class=\"kw-alerte\">auto-réinfestation digestive</span> chez l'<span class=\"kw-clinique\">immunodéprimé</span>, surtout sous <span class=\"kw-ttt\">corticothérapie</span>) ; <span class=\"kw-alerte\">DRESS</span> (drug <span class=\"kw-clinique\">rash</span> with eosinophilia and systemic symptoms)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Toute <span class=\"kw-alerte\">défaillance d'organe</span> — <span class=\"kw-alerte\">respiratoire</span>, <span class=\"kw-alerte\">cardiaque</span> ou <span class=\"kw-alerte\">neurologique</span> — impose une <span class=\"kw-ttt\">hospitalisation</span> et un <span class=\"kw-ttt\">avis spécialisé</span> pour la prise en charge des fonctions vitales et un <span class=\"kw-ttt\">traitement étiologique ou présomptif</span>.</div>","frequence":0},{"id":"218-10","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier un syndrome d’hypersensibilité médicamenteuse sévère","contenu":"<p>Le <span class=\"kw-def\">DRESS</span> (<em>drug <span class=\"kw-clinique\">rash</span> with eosinophilia and systemic symptoms</em>) est le <span class=\"kw-def\">syndrome d'hypersensibilité médicamenteuse sévère</span> à reconnaître devant une éosinophilie.</p>\n      <p>Une cause <span class=\"kw-ttt\">médicamenteuse</span> doit être évoquée <strong>systématiquement</strong> devant une éosinophilie : l'élément essentiel du diagnostic est le <strong>lien temporel</strong> entre l'<span class=\"kw-ttt\">introduction du traitement</span> et l'apparition de l'éosinophilie. L'expression clinique va de la forme <span class=\"kw-clinique\">asymptomatique</span> au simple <span class=\"kw-clinique\">rash cutané</span>, jusqu'au <span class=\"kw-alerte\">DRESS</span> constitué, qui est une <span class=\"kw-alerte\">urgence</span>.</p>\n      <div class=\"callout callout-warn\"><strong>À compléter (trou de la fiche source).</strong> La fiche <code>218-eosinophilie.md</code> nomme le <span class=\"kw-alerte\">DRESS</span> sans en détailler <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">critères diagnostiques</span> (<span class=\"kw-clinique\">délai d'apparition</span>, <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">adénopathies</span>, <span class=\"kw-alerte\">atteintes viscérales</span>, <span class=\"kw-chiffre\">score RegiSCAR</span>, <span class=\"kw-alerte\">mortalité</span>). À enrichir depuis les référentiels des items 186 / 187 / 325.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 186 — <span class=\"kw-ci\">Hypersensibilité</span> - allergie · 187 — Hypersensibilité, allergies cutanées · 325 — Gestions des risques liés aux médicaments (<span class=\"kw-etio\">iatrogène</span>, erreur)</em></p>","frequence":0},{"id":"218-11","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales étiologies parasitaires des éosinophilies chez un patient n’ayant pas séjourné hors France métropolitaine","contenu":"<p>Chez un patient <strong>n'ayant pas séjourné</strong> hors de France métropolitaine, <span class=\"kw-clinique\">les</span> helminthoses suivantes donnent une <span class=\"kw-def\">éosinophilie modérée</span> (<span class=\"kw-chiffre\">&lt; 1,5 G/L</span>) : il n'y a <strong>pas de migration tissulaire</strong>.</p>\n      <table >\n        <thead><tr><th>Parasite</th><th>Présentation</th><th>Diagnostic</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Oxyurose</span> (<em>Enterobius vermicularis</em>)</td><td><span class=\"kw-clinique\">Prurit anal</span>, surtout chez l'enfant</td><td><span class=\"kw-bio\">Scotch test</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Taeniasis</span> (<em>Taenia saginata</em>)</td><td>Ingestion de viande de bœuf crue ou mal cuite ; <span class=\"kw-clinique\">dyspepsie</span></td><td><span class=\"kw-bio\">EPS</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Anisakiase</span> (<em>Anisakis</em>)</td><td>Ingestion de <span class=\"kw-clinique\">poissons crus</span> ; signes digestifs</td><td><span class=\"kw-bio\">Sérologie</span> ; <span class=\"kw-imagerie\">gastroscopie</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Hydatidose</span> (<em>Echinococcus granulosus</em>)</td><td>Aliments / eau souillés par des déjections canines ; <span class=\"kw-clinique\">kystes hépatiques</span></td><td><span class=\"kw-bio\">Sérologie</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Échinococcose alvéolaire</span> (<em>E. multilocularis</em>)</td><td>Est de la France</td><td><span class=\"kw-bio\">Sérologie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Comme pour toute helminthose, <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">corticoïdes sont contre-indiqués</span> en cas d'hyperéosinophilie d'origine <span class=\"kw-etio\">parasitaire</span> — risque d'hyperinfestation parasitaire (cf. obj-2).</div>","frequence":0},{"id":"218-12","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales étiologies parasitaires des éosinophilies chez un patient ayant séjourné en zone tropicale/hors France métropolitaine","contenu":"<p>Chez un patient ayant <strong>séjourné en zone tropicale</strong>, <span class=\"kw-clinique\">les</span> helminthoses se regroupent sous le mnémo <span class=\"kw-def\">BAFAD</span>.</p>\n      <table >\n        <thead><tr><th>Helminthose</th><th>Moyens diagnostiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">B — Bilharzioses / schistosomoses</span></td><td><span class=\"kw-bio\">Sérologie</span> ; <span class=\"kw-bio\">EPS</span> (bilharziose digestive) ; <span class=\"kw-bio\">examen parasitologique des urines</span> (bilharziose urinaire à <em>S. haematobium</em>)</td></tr>\n          <tr><td><span class=\"kw-etio\">A — Anguillulose / strongyloïdose</span></td><td><span class=\"kw-bio\">Sérologie</span> ; <span class=\"kw-bio\">EPS</span> avec techniques de concentration</td></tr>\n          <tr><td><span class=\"kw-etio\">F — Filarioses</span> (loase, filariose lymphatique, onchocercose)</td><td><span class=\"kw-bio\">Sérologie</span> ; recherche de <span class=\"kw-bio\">microfilaires</span> — sang (prélèvement <strong>diurne</strong> : loase ; <strong>nocturne</strong> : filarioses lymphatiques), <span class=\"kw-bio\">biopsie</span> cutanée exsangue / nodules (onchocercose)</td></tr>\n          <tr><td><span class=\"kw-etio\">A — Ascaridiose</span></td><td><span class=\"kw-bio\">EPS</span></td></tr>\n          <tr><td><span class=\"kw-etio\">D — Distomatose</span></td><td><span class=\"kw-bio\">Sérologie</span> ; <span class=\"kw-bio\">EPS</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> <span class=\"kw-clinique\">AEG</span> + <span class=\"kw-clinique\">fièvre</span> + hyperéosinophilie + manifestations viscérales → étiologie <span class=\"kw-etio\">parasitaire</span> très probable (la <span class=\"kw-bio\">sérologie</span> peut être trop précoce pour documenter une séroconversion).</div>","frequence":1},{"id":"218-13","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales causes non parasitaires d’une éosinophilie","contenu":"<p>De très nombreuses causes <strong>non parasitaires</strong> peuvent induire une éosinophilie. Elles se classent en grandes catégories.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Infections</strong></td><td><span class=\"kw-etio\">VIH</span> ; <span class=\"kw-etio\">HTLV-1</span> ; septicémies ; <span class=\"kw-etio\">brucellose</span> ; scarlatine ; mycose profonde ; <span class=\"kw-etio\">syphilis secondaire</span> ; <span class=\"kw-etio\">mononucléose infectieuse</span> ; <span class=\"kw-def\">hépatite</span> C ; <span class=\"kw-etio\">endocardite d'Osler</span> ; mycobactéries</td></tr>\n          <tr><td><strong>Atopie</strong></td><td><strong><span class=\"kw-def\">Terrain</span> :</strong> ATCD d'atopie, <span class=\"kw-def\">asthme</span>, rhinite spasmodique, <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-etio\">atopique</span>, <span class=\"kw-clinique\">urticaire</span><br><strong>Tableau :</strong> éosinophilie <strong>modérée</strong> <span class=\"kw-chiffre\">&lt; 1 G/L</span>, variable dans le temps, + <span class=\"kw-bio\">IgE totales</span> élevées<br><strong>Nuance :</strong> ne pas retenir un diagnostic d'atopie devant une hyperéosinophilie <span class=\"kw-chiffre\">&gt; 1,5 G/L</span> ; le dosage des <span class=\"kw-chiffre\">IgE</span> totales n'oriente pas (peut être normal en cas d'<span class=\"kw-ci\">allergie</span>, élevé pour une autre cause)</td></tr>\n          <tr><td><strong>Médicaments</strong></td><td>À évoquer <strong>systématiquement</strong> ; <strong>lien temporel</strong> avec l'introduction du traitement = élément essentiel ; tableau allant du <span class=\"kw-clinique\">rash cutané</span> isolé au <span class=\"kw-alerte\">DRESS</span></td></tr>\n          <tr><td><strong>Toxiques</strong></td><td><span class=\"kw-etio\">Benzène</span> ; <span class=\"kw-etio\">mercure</span></td></tr>\n          <tr><td><strong>Cancers &amp; hémopathies</strong></td><td>Hyperéosinophilie par excès de production d'<span class=\"kw-bio\">IL-5</span>, à évoquer en premier lieu : <span class=\"kw-etio\">lymphome hodgkinien</span> ; lymphome T systémique ; lymphomes cutanés ; <span class=\"kw-etio\">LAL</span> ; carcinomes mucosécrétants et cancers solides (digestifs ++, pulmonaires ++, rénaux, thyroïdiens)</td></tr>\n          <tr><td><strong>Maladies systémiques</strong></td><td><span class=\"kw-etio\">GEPA</span> ; périartérite noueuse ; <span class=\"kw-etio\">polyarthrite rhumatoïde</span> ; polymyosite ; <span class=\"kw-etio\">lupus</span> ; pemphigoïde bulleuse ; insuffisance surrénale ; maladie des emboles de cristaux de <span class=\"kw-bio\">cholestérol</span> ; rejet de greffon ; certains déficits immunitaires</td></tr>\n          <tr><td><strong>Maladies spécifiques d'organes</strong></td><td><strong>ORL / bronchopulmonaire :</strong> <span class=\"kw-clinique\">syndrome de Fernand</span> Widal ; <span class=\"kw-def\">pneumonie</span> chronique à <span class=\"kw-bio\">éosinophiles</span> (maladie de Carrington)<br><strong>Digestif :</strong> gastro-entérite à <span class=\"kw-bio\">éosinophiles</span> ; <span class=\"kw-etio\">Crohn</span> ; <span class=\"kw-etio\">RCH</span> ; maladie de Whipple<br><strong>Hépato-biliaire :</strong> cholangite sclérosante ; <span class=\"kw-def\">cirrhose</span> biliaire primitive<br><strong>Cutané :</strong> maladie de Kimura ; lymphome cutané ; mastocytose</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 193 — <span class=\"kw-def\">Vascularite</span> systémique · 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 319 — Lymphome malin · 282 — <span class=\"kw-def\">MICI</span> · 325 — Gestions des risques liés aux médicaments (<span class=\"kw-etio\">iatrogène</span>, erreur)</em></p>","frequence":1},{"id":"218-14","rang":"B","rubrique":"Étiologies","titre":"Connaître les autres étiologies parasitaires des éosinophilies chez un patient n’ayant pas séjourné hors France métropolitaine","contenu":"<p>Toujours chez un patient <strong>n'ayant pas séjourné</strong> hors de France métropolitaine, d'autres helminthoses donnent au contraire une <span class=\"kw-def\">hyperéosinophilie</span> (<span class=\"kw-chiffre\">&gt; 1,5 G/L</span>) : il existe ici une <strong>migration tissulaire</strong> du parasite.</p>\n      <table >\n        <thead><tr><th>Parasite</th><th>Présentation</th><th>Diagnostic</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Distomatose hépatique</span> (<em>Fasciola hepatica</em>)</td><td>Ingestion de <span class=\"kw-clinique\">cresson</span> ; tableau d'<span class=\"kw-clinique\">angiocholite</span> (<span class=\"kw-clinique\">ictère</span> fébrile)</td><td><span class=\"kw-bio\">Sérologie</span> ; imagerie</td></tr>\n          <tr><td><span class=\"kw-etio\">Myiase</span></td><td><span class=\"kw-clinique\">Tuméfaction sous-cutanée</span> ; régions d'élevage bovin</td><td>Clinique</td></tr>\n          <tr><td><span class=\"kw-etio\">Trichinose</span> (<em>Trichinella spiralis</em>)</td><td>Ingestion de viande de porc, sanglier ou cheval insuffisamment cuite ; <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">œdèmes</span>, <span class=\"kw-clinique\">myalgies</span></td><td><span class=\"kw-bio\">Sérologie</span> ; <span class=\"kw-bio\">biopsie musculaire</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Toxocarose</span> (<em>Toxocara canis / cati</em>)</td><td>Aliments souillés par déjections de chien ou de chat, bacs à sable ; possible asymptomatique ; <span class=\"kw-clinique\">syndrome de larva migrans viscérale</span> (tous <span class=\"kw-clinique\">les</span> organes) ; <span class=\"kw-clinique\">prurit</span>, signes digestifs et respiratoires, localisations oculaires parfois sévères</td><td><span class=\"kw-bio\">Sérologie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Comme pour toute helminthose, <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">corticoïdes sont contre-indiqués</span> tant que le diagnostic <span class=\"kw-etio\">parasitaire</span> n'est pas écarté (cf. obj-2).</div>","frequence":0},{"id":"218-15","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens paracliniques de première intention à demander en cas d’éosinophilie","contenu":"<p>Devant une éosinophilie, le bilan paraclinique de <strong>1ʳᵉ intention</strong> combine recherche étiologique et bilan de retentissement.</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Biologie</strong></td><td><strong><span class=\"kw-bio\">NFS</span> + frottis :</strong> blastes → leucémie aiguë ; myélémie → syndrome myéloprolifératif ; cellules de Sézary → lymphome T cutané ; microfilaires → parasitose<br><strong>Autres :</strong> <span class=\"kw-bio\">ionogramme sanguin</span> ; <span class=\"kw-bio\">créatinine</span> ; <span class=\"kw-bio\">bilan hépatique</span> ; <span class=\"kw-bio\">tests de coagulation</span> ; <span class=\"kw-bio\">créatine kinase</span></td></tr>\n          <tr><td><strong>Microbiologie</strong></td><td><strong><span class=\"kw-bio\">Sérologies</span> :</strong> <span class=\"kw-bio\">VIH</span> ; <span class=\"kw-bio\">toxocarose</span> et <span class=\"kw-bio\">distomatose</span> (même en l'absence de signe ou de voyage)<br><strong><span class=\"kw-bio\">EPS</span> :</strong> 3 examens parasitologiques des selles espacés de quelques jours<br><strong>Si séjour tropical :</strong> examen parasitologique des urines (Afrique subsaharienne) ; recherche de <span class=\"kw-bio\">microfilaires</span> ; <span class=\"kw-bio\">IgE totales</span> ; <span class=\"kw-bio\">sérologies</span> filarioses / bilharziose / strongyloïdose</td></tr>\n          <tr><td><strong>Retentissement</strong></td><td><span class=\"kw-imagerie\">ECG</span> + <span class=\"kw-imagerie\">ETT</span> pour le bilan du retentissement d'une éosinophilie <strong>persistante</strong> — quel que soit son chiffre</td></tr>\n          <tr><td><strong>Autres</strong></td><td>Examens d'<span class=\"kw-imagerie\">imagerie</span> (toxocarose, distomatose) ; <span class=\"kw-bio\">biopsie musculaire</span> (trichinellose) dans des cas précis</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Une éosinophilie persistante malgré des explorations de 1ʳᵉ intention négatives doit être prise en charge en <strong>milieu spécialisé</strong> (recherche de causes rares + bilan du retentissement).</div>\n\n      <figure class=\"algo-fig\" aria-label=\"Algorithme — conduite à tenir devant une éosinophilie\">\n        <figcaption class=\"algo-cap\">Conduite à tenir devant une éosinophilie <span>— retranscrit du référentiel (fig. F-218-1)</span></figcaption>\n        <div class=\"algo-218\">\n          <div class=\"algo-box algo-start\">Éosinophilie confirmée <strong>&gt; 0,<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> G/L</span></strong> sur 2 <span class=\"kw-bio\">NFS</span></div>\n          <div class=\"algo-link\"></div>\n          <div class=\"algo-box algo-step\">Anamnèse ciblée (allergènes, atopie, médicaments, voyage, <span class=\"kw-def\">comorbidités</span>) + examen clinique complet (peau, poumon, foie, neuro) + bilan non spécifique (<span class=\"kw-bio\">NFS</span>-<span class=\"kw-bio\">plaquettes</span>, <span class=\"kw-bio\">ionogramme</span>-<span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-imagerie\"><span class=\"kw-imagerie\">radiographie</span> thoracique</span>, <span class=\"kw-bio\">ECG</span>)</div>\n          <div class=\"algo-link\"></div>\n          <div class=\"algo-box algo-decision\"><span class=\"kw-alerte\">Signes de gravité</span> clinique ?</div>\n          <div class=\"algo-fork\">\n            <div class=\"algo-arm\">\n              <span class=\"algo-tag algo-tag-oui\">OUI</span>\n              <div class=\"algo-box algo-crit\">Éosinophilie &gt; 1,<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> G/L</span> depuis <span class=\"kw-chiffre\">≥ 6 mois</span> · syndrome d'invasion larvaire · <span class=\"kw-clinique\">syndrome de lyse</span> <span class=\"kw-etio\">parasitaire</span> · syndrome d'hyperinfestation à <em>Strongyloïdes</em> · <span class=\"kw-alerte\">détresse</span> respiratoire ou cardiovasculaire</div>\n              <div class=\"algo-link algo-link-sm\"></div>\n              <div class=\"algo-box algo-urgent\">Avis spécialisé — traitement présomptif ou étiologique, <span class=\"kw-ttt\">corticothérapie</span> symptomatique, <span class=\"kw-alerte\">hospitalisation</span> pour la prise en charge des fonctions vitales</div>\n            </div>\n            <div class=\"algo-arm\">\n              <span class=\"algo-tag algo-tag-non\">NON</span>\n              <div class=\"algo-box algo-decision algo-decision-sm\">Niveau d'éosinophilie ?</div>\n              <div class=\"algo-fork algo-fork-sub\">\n                <div class=\"algo-arm\">\n                  <span class=\"algo-tag\">Légère — 0,5 à 1,<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> G/L</span></span>\n                  <div class=\"algo-box algo-out\">Pas de dysfonction d'organe → atopie · <span class=\"kw-ci\">allergie</span> médicamenteuse · oxyurose · taeniasis · échinococcose alvéolaire</div>\n                </div>\n                <div class=\"algo-arm\">\n                  <span class=\"algo-tag\">Modérée à sévère — &gt; 1,<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> G/L</span></span>\n                  <div class=\"algo-box algo-decision algo-decision-sm\">Voyage en zone tropicale ?</div>\n                  <div class=\"algo-fork algo-fork-sub\">\n                    <div class=\"algo-arm\">\n                      <span class=\"algo-tag algo-tag-oui\">OUI</span>\n                      <div class=\"algo-box algo-out\"><strong>Asymptomatique :</strong> anguillulose, filariose<br><strong>Symptomatique :</strong> bilharziose, distomatose, gnathostomose</div>\n                    </div>\n                    <div class=\"algo-arm\">\n                      <span class=\"algo-tag algo-tag-non\">NON</span>\n                      <div class=\"algo-box algo-out\"><strong>Asymptomatique :</strong> toxocarose, distomatose<br><strong>Symptomatique :</strong> <span class=\"kw-def\">vascularite</span>, cancer, hémopathie, ascaridiose, trichinellose, distomatose, toxocarose</div>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 214 — Thrombopénie · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Retentissement viscéral de l'hyperéosinophilie</strong></p><p><span class=\"kw-ttt\">Hospitalisation</span> pour prise en charge des <span class=\"kw-alerte\">fonctions vitales</span> + <span class=\"kw-ttt\">avis spécialisé</span></p><ul><li><span class=\"kw-alerte\">Défaillance respiratoire</span></li><li><span class=\"kw-alerte\">Défaillance cardiaque</span></li><li><span class=\"kw-alerte\">Défaillance neurologique</span> (parfois d'origine <span class=\"kw-alerte\">thrombotique artérielle</span>)</li></ul><p><strong>Étiologies graves <span class=\"q\">— à traiter sans délai</span></strong></p><p><span class=\"kw-ttt\">Traitement étiologique ou présomptif</span> sans attendre</p><ul><li><span class=\"kw-alerte\">Atteinte cardiaque</span> d'une <span class=\"kw-etio\">GEPA</span></li><li><span class=\"kw-etio\">Hémopathies malignes</span></li><li><span class=\"kw-alerte\">Anguillulose maligne</span> (<span class=\"kw-alerte\">auto-réinfestation digestive</span> chez l'<span class=\"kw-clinique\">immunodéprimé</span>, surtout sous <span class=\"kw-ttt\">corticothérapie</span>)</li><li><span class=\"kw-alerte\">DRESS</span> (drug <span class=\"kw-clinique\">rash</span> with eosinophilia and systemic symptoms)</li></ul>","hospit":"<p><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> toute <span class=\"kw-alerte\">défaillance d'organe</span> (<span class=\"kw-alerte\">respiratoire</span>, <span class=\"kw-alerte\">cardiaque</span> ou <span class=\"kw-alerte\">neurologique</span>) → prise en charge des fonctions vitales + <span class=\"kw-ttt\">avis spécialisé</span>.<br><strong>Milieu spécialisé :</strong> <span class=\"kw-def\">éosinophilie persistante</span> malgré un bilan de <span class=\"kw-chiffre\">1ʳᵉ intention</span> négatif → recherche de causes rares + <span class=\"kw-bio\">bilan de retentissement</span>.<br><strong>Avis hématologique :</strong> suspicion d'<span class=\"kw-def\">éosinophilie clonale</span> / <span class=\"kw-def\">syndrome hyperéosinophilique</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Défaillance respiratoire, cardiaque ou neurologique</span> (parfois d'origine <span class=\"kw-alerte\">thrombotique artérielle</span>)</li><li><span class=\"kw-alerte\">Fibrose endomyocardique / endocardite de Loffler</span> — <span class=\"kw-def\">cardiomyopathie restrictive</span> souvent <span class=\"kw-alerte\">irréversible et fatale</span></li><li><span class=\"kw-alerte\">Thromboses vasculaires</span> artérielles ou veineuses</li><li><span class=\"kw-alerte\">DRESS</span> — <span class=\"kw-def\">syndrome d'hypersensibilité médicamenteuse sévère</span></li><li><span class=\"kw-alerte\">Anguillulose maligne</span> par <span class=\"kw-alerte\">auto-réinfestation digestive</span> chez l'<span class=\"kw-clinique\">immunodéprimé</span> (surtout sous <span class=\"kw-ttt\">corticothérapie</span>)</li><li><span class=\"kw-clinique\">AEG</span> + <span class=\"kw-clinique\">fièvre</span> + hyperéosinophilie + <span class=\"kw-alerte\">manifestations viscérales</span> → <span class=\"kw-etio\">étiologie parasitaire</span> très probable</li></ul>","principes":"<p>Traitement avant tout <span class=\"kw-def\">étiologique</span>. La gravité tient à l'<span class=\"kw-alerte\">infiltration tissulaire</span> par <span class=\"kw-clinique\">les</span> PNE (et non au chiffre sanguin) : un <span class=\"kw-bio\">bilan de retentissement</span> (<span class=\"kw-imagerie\">ECG</span> + <span class=\"kw-imagerie\">ETT</span>) s'impose devant toute éosinophilie <strong>persistante</strong>, quel que soit son chiffre.</p><p><strong>Helminthose (parasitose)</strong></p><p><span class=\"kw-ci\">Corticoïdes formellement contre-indiqués</span> — risque d'<span class=\"kw-alerte\">hyperinfestation parasitaire</span> (anguillulose maligne)</p><ul><li><span class=\"kw-ttt\">Traitement antiparasitaire</span> ciblé selon le parasite</li><li><span class=\"kw-ttt\">Traitement d'épreuve</span> possible si enquête non concluante : <span class=\"kw-ttt\">albendazole</span> ou <span class=\"kw-ttt\">flubendazole</span>, avec <span class=\"kw-def\">suivi</span> du <span class=\"kw-bio\">taux de PNE</span></li></ul><p><strong>Cause médicamenteuse / <span class=\"kw-alerte\">DRESS</span></strong></p><p><span class=\"kw-alerte\">DRESS</span> constitué = <span class=\"kw-alerte\">urgence</span> → <span class=\"kw-ttt\">avis spécialisé</span></p><ul><li>Cause <span class=\"kw-ttt\">médicamenteuse</span> à évoquer systématiquement ; le <strong>lien temporel</strong> avec l'introduction du traitement est l'élément essentiel du diagnostic</li></ul><p><strong>Syndrome hyperéosinophilique (SHE) / éosinophilie clonale</strong></p><p><span class=\"kw-def\">Pronostic</span> <span class=\"kw-alerte\">sombre en l'absence de traitement</span> → <span class=\"kw-ttt\">avis hématologique spécialisé</span></p><ul><li><span class=\"kw-def\">SHE myéloïde</span> (clonal) : <span class=\"kw-ttt\">imatinib</span>, médicament de choix dans la plupart des SHE</li><li><span class=\"kw-def\">SHE lymphoïde</span> : <span class=\"kw-ttt\">bonne réponse à la corticothérapie</span></li></ul><p><strong>Retentissement viscéral / situation d'<span class=\"kw-alerte\">urgence</span></strong></p><p><span class=\"kw-ttt\">Avis spécialisé</span> sans délai</p><ul><li><span class=\"kw-ttt\">Hospitalisation</span> pour prise en charge des <span class=\"kw-alerte\">fonctions vitales</span></li><li><span class=\"kw-ttt\">Traitement présomptif ou étiologique</span> + <span class=\"kw-ttt\">corticothérapie symptomatique</span> (après avoir éliminé une <span class=\"kw-etio\">helminthose</span>)</li></ul>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-218.pdf","label":"Pilly étudiant — Pilly 2023 item 218"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Éosinophilie : signes de gravité ? — Après anamnèse + examen clinique complet + bilan non spécifique","detail":"<h4>CAT — démarche diagnostique devant une éosinophilie — Éosinophilie persistante confirmée sur 2 <span class=\"kw-bio\">NFS</span> — d'après l'algorithme du référentiel</h4>","branches":[{"to":"t-urgence","label":"Oui — signes de gravité","color":"red"},{"to":"q-niveau","label":"Non — pas de signe de gravité","color":"blue"}]},{"id":"t-urgence","kind":"terminal","label":"Urgence — avis spécialisé et hospitalisation","color":"red","detail":"<h4><span class=\"kw-alerte\"><span class=\"kw-def\">Critères de</span> gravité</span></h4><ul><li><span class=\"kw-chiffre\">Éosinophilie &gt; 1,5 G/L</span> depuis <span class=\"kw-chiffre\">≥ 6 mois</span></li><li><span class=\"kw-alerte\">Syndrome d'invasion larvaire</span> · <span class=\"kw-alerte\">syndrome de lyse parasitaire</span></li><li><span class=\"kw-alerte\">Syndrome d'hyperinfestation</span> à <em>Strongyloïdes</em></li><li><span class=\"kw-alerte\">Détresse respiratoire ou cardiovasculaire</span></li></ul><h4>Étiologies graves</h4><ul><li><span class=\"kw-alerte\">Atteinte cardiaque</span> d'une <span class=\"kw-etio\">GEPA</span></li><li><span class=\"kw-etio\">Hémopathies malignes</span></li><li><span class=\"kw-alerte\">Anguillulose maligne</span> (auto-réinfestation chez l'<span class=\"kw-clinique\">immunodéprimé</span>)</li><li><span class=\"kw-alerte\">DRESS</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Avis spécialisé</span> + <span class=\"kw-ttt\">hospitalisation</span> pour la prise en charge des fonctions vitales</li><li><span class=\"kw-ttt\">Traitement présomptif ou étiologique</span> + <span class=\"kw-ttt\">corticothérapie symptomatique</span></li></ul><h4>Piège</h4><ul><li><span class=\"kw-ci\">Corticoïdes contre-indiqués</span> tant qu'une <span class=\"kw-etio\">helminthose</span> n'est pas écartée (risque d'<span class=\"kw-alerte\">hyperinfestation</span>)</li></ul><h4>Renvoi</h4><ul><li>Item 193 (<span class=\"kw-clinique\">vascularite</span> — GEPA) · Item 234 (<span class=\"kw-ci\">insuffisance cardiaque</span> — <span class=\"kw-clinique\">endocardite</span> de Loffler) · Item 319 (lymphome malin)</li></ul>"},{"id":"q-niveau","kind":"decision","label":"Niveau d'éosinophilie ? — Valeur absolue des PNE (jamais le pourcentage)","branches":[{"to":"t-legere","label":"Légère — 0,5 à 1,5 G/L","color":"green"},{"to":"q-voyage","label":"Modérée à sévère — > 1,5 G/L","color":"amber"}]},{"id":"t-legere","kind":"terminal","label":"Éosinophilie légère — causes fréquentes","color":"green","detail":"<h4>Contexte</h4><ul><li>Pas de <span class=\"kw-alerte\">dysfonction d'organe</span> ; éosinophilie modérée <span class=\"kw-chiffre\">&lt; 1 G/L</span> variable dans le temps oriente vers l'<span class=\"kw-etio\">atopie</span></li></ul><h4>Causes à évoquer</h4><ul><li><span class=\"kw-etio\">Atopie</span> (asthme, rhinite, <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-etio\">atopique</span>, <span class=\"kw-clinique\">urticaire</span>)</li><li><span class=\"kw-etio\">Allergie médicamenteuse</span></li><li><span class=\"kw-etio\">Oxyurose</span> · <span class=\"kw-etio\">taeniasis</span> · <span class=\"kw-etio\">échinococcose alvéolaire</span></li></ul><h4>Renvoi</h4><ul><li>Item 186 (<span class=\"kw-ci\">hypersensibilité</span> - allergie) · Item 325 (gestion des risques liés aux médicaments — <span class=\"kw-etio\">iatrogène</span>)</li></ul>"},{"id":"q-voyage","kind":"decision","label":"Séjour en zone tropicale ? — Oriente l'enquête parasitaire (helminthoses)","branches":[{"to":"t-tropical","label":"Oui — zone tropicale","color":"amber"},{"to":"t-metropole","label":"Non — France métropolitaine","color":"amber"}]},{"id":"t-tropical","kind":"terminal","label":"Helminthoses tropicales (BAFAD)","color":"amber","detail":"<h4>Asymptomatique</h4><ul><li><span class=\"kw-etio\">Anguillulose</span> · <span class=\"kw-etio\">filariose</span></li></ul><h4>Symptomatique</h4><ul><li><span class=\"kw-etio\">Bilharziose</span> · <span class=\"kw-etio\">distomatose</span> · <span class=\"kw-etio\">gnathostomose</span></li></ul><h4>Mnémo BAFAD</h4><ul><li><span class=\"kw-etio\">B</span>ilharzioses · <span class=\"kw-etio\">A</span>nguillulose · <span class=\"kw-etio\">F</span>ilarioses · <span class=\"kw-etio\">A</span>scaridiose · <span class=\"kw-etio\">D</span>istomatose</li></ul><h4>Diagnostic</h4><ul><li><span class=\"kw-bio\">Sérologies</span> parasitaires (analyses <span class=\"kw-clinique\">les</span> plus contributives)</li><li><span class=\"kw-bio\">EPS</span> x3 ; <span class=\"kw-bio\">examen parasitologique des urines</span> si <em>S. haematobium</em></li><li>Recherche de <span class=\"kw-bio\">microfilaires</span> — sang <strong>diurne</strong> (loase) / <strong>nocturne</strong> (filarioses lymphatiques)</li></ul><h4>Piège</h4><ul><li><span class=\"kw-ci\">Corticoïdes contre-indiqués</span> (risque d'<span class=\"kw-alerte\">hyperinfestation parasitaire</span>)</li></ul>"},{"id":"t-metropole","kind":"terminal","label":"France métropolitaine — hyperéosinophilie","color":"amber","detail":"<h4>Helminthoses (migration tissulaire)</h4><ul><li><span class=\"kw-etio\">Distomatose hépatique</span> (cresson, <span class=\"kw-clinique\">angiocholite</span>)</li><li><span class=\"kw-etio\">Trichinose</span> · <span class=\"kw-etio\">toxocarose</span> (larva migrans viscérale) · <span class=\"kw-etio\">ascaridiose</span></li></ul><h4>Causes non parasitaires</h4><ul><li><span class=\"kw-etio\">Vascularite</span> (GEPA) · <span class=\"kw-etio\">cancer</span> · <span class=\"kw-etio\">hémopathie</span></li></ul><h4>Diagnostic <span class=\"kw-etio\">parasitaire</span></h4><ul><li><span class=\"kw-bio\">Sérologies toxocarose et distomatose</span> (même sans signe ni voyage)</li><li><span class=\"kw-bio\">EPS</span> ; <span class=\"kw-bio\">biopsie musculaire</span> (trichinellose)</li></ul><h4>Renvoi</h4><ul><li>Item 193 (<span class=\"kw-clinique\">vascularite</span> systémique) · Item 319 (lymphome malin)</li></ul>"}]},"cards":[{"i":"0f4ff1967a20","n":218,"o":"218-1","u":"Définition","t":"Connaître la définition de l’éosinophilie","q":"Quel est le piège diagnostique classique concernant l'éosinophilie ?","a":"<p>Le piège classique est de se fier au <strong>pourcentage de PNE</strong> dans la formule leucocytaire. Le diagnostic repose uniquement sur la <strong>valeur absolue des PNE</strong> circulants.</p>"},{"i":"2fe403a84078","n":218,"o":"218-1","u":"Définition","t":"Connaître la définition de l’éosinophilie","q":"Comment définir l'éosinophilie ?","a":"<p>L'éosinophilie se définit comme une <strong>augmentation du nombre de polynucléaires éosinophiles (PNE) circulants</strong>, constatée sur plusieurs NFS successives, le caractère <strong>persistant</strong> étant essentiel au diagnostic.</p>"},{"i":"78214ff639e6","n":218,"o":"218-1","u":"Définition","t":"Connaître la définition de l’éosinophilie","q":"Quelle cytokine est prépondérante dans l'éosinophilopoïèse ?","a":"<p>L'éosinophilopoïèse dépend surtout de l'<strong>interleukine 5 (IL-5)</strong>, qui assure la production, la différenciation et le passage médullo-sanguin des PNE.</p>"},{"i":"c897ec7210f3","n":218,"o":"218-1","u":"Définition","t":"Connaître la définition de l’éosinophilie","q":"Quels sont les seuils de l'éosinophilie et de l'hyperéosinophilie en valeur absolue ?","a":"<ul><li>Une éosinophilie modérée se situe entre <strong>0,5 et 1,5 G/L</strong> (médecine interne) ou <strong>0,5 et 1 G/L</strong> (hématologie) de PNE.</li><li>Une hyperéosinophilie est définie par un taux de PNE <strong>supérieur à 1,5 G/L</strong>.</li></ul>"},{"i":"032fe418774f","n":218,"o":"218-10","u":"Identifier une urgence","t":"Identifier un syndrome d’hypersensibilité médicamenteuse sévère","q":"Comment doit-on systématiquement évaluer une éosinophilie dans le contexte de l'urgence ?","a":"<p>Devant une éosinophilie, une <strong>cause médicamenteuse</strong> doit être évoquée systématiquement. L'élément essentiel du diagnostic est le <strong>lien temporel entre l'introduction du traitement et l'apparition de l'éosinophilie</strong>.</p>"},{"i":"3a242dd4be89","n":218,"o":"218-10","u":"Identifier une urgence","t":"Identifier un syndrome d’hypersensibilité médicamenteuse sévère","q":"Quelle est la forme la plus sévère du syndrome d'hypersensibilité médicamenteuse associée à une éosinophilie, et pourquoi est-ce une urgence ?","a":"<p>La forme la plus sévère est le <strong>DRESS (Drug Rash with Eosinophilia and Systemic Symptoms)</strong>. C'est une <strong>urgence vitale</strong> qui nécessite une reconnaissance rapide et une prise en charge adaptée en raison de son potentiel de gravité et de ses complications systémiques.</p>"},{"i":"b0b818cd0fa9","n":218,"o":"218-10","u":"Identifier une urgence","t":"Identifier un syndrome d’hypersensibilité médicamenteuse sévère","q":"Quel est le spectre de la présentation clinique d'un syndrome d'hypersensibilité médicamenteuse associé à une éosinophilie ?","a":"<p>L'expression clinique est très variable, allant de la forme <strong>asymptomatique</strong>, au <strong>simple rash cutané</strong>, jusqu'au <strong>DRESS constitué</strong> qui représente une urgence vitale.</p>"},{"i":"0ef246e8b91b","n":218,"o":"218-3","u":"Diagnostic positif","t":"Savoir que parmi les parasitoses ce sont essentiellement les helminthoses qui en sont responsables","q":"Dans quel cas un traitement d'épreuve est-il envisagé pour une helminthose, et quel est le piège majeur à éviter lors de la prise en charge d'une hyperéosinophilie secondaire à une helminthose ?","a":"<p>Un <strong>traitement d'épreuve</strong> par <strong>albendazole</strong> ou <strong>flubendazole</strong> peut être envisagé si l'enquête parasitologique n'est pas concluante, avec un suivi du taux de PNN.</p><p>Le piège majeur est la <strong>contre-indication formelle des corticoïdes</strong> en cas d'hyperéosinophilie secondaire à une helminthose, en raison du risque d'<strong>hyperinfestation parasitaire</strong> (<strong>anguillulose maligne</strong> par auto-réinfestation digestive).</p>"},{"i":"173485324a67","n":218,"o":"218-3","u":"Diagnostic positif","t":"Savoir que parmi les parasitoses ce sont essentiellement les helminthoses qui en sont responsables","q":"Quelle est la principale catégorie de parasitoses responsable d'une éosinophilie et quels sont les types de parasitoses qui n'en entraînent quasiment jamais ?","a":"<p>En cas d'éosinophilie, les parasitoses responsables sont majoritairement les <strong>helminthoses</strong> (vers).</p><p>Les <strong>protozooses</strong> en revanche n'en entraînent quasiment jamais. Le mémo <strong>PLAT</strong> permet de retenir les 4 parasitoses sans éosinophilie : <ul><li><strong>P</strong>aludisme</li><li><strong>L</strong>eishmaniose</li><li><strong>A</strong>mibiase</li><li><strong>T</strong>rypanosomiases</li></ul></p>"},{"i":"59c692b5df8b","n":218,"o":"218-3","u":"Diagnostic positif","t":"Savoir que parmi les parasitoses ce sont essentiellement les helminthoses qui en sont responsables","q":"Quels sont les examens complémentaires à privilégier pour le diagnostic d'une helminthose, et dans quel contexte sont-ils indiqués ?","a":"<p>Devant une suspicion d'helminthose, les examens complémentaires sont guidés par l'interrogatoire (notion de <strong>voyage</strong>) et la clinique :</p><ul><li>Les <strong>sérologies parasitaires</strong> sont les analyses les plus contributives et applicables à de nombreux helminthes.</li><li>Le <strong>diagnostic direct</strong> inclut l'examen parasitologique des selles (recherche d'œufs pour ascaridiose, distomatose, bilharziose sauf <em>S. haematobium</em>), l'examen parasitologique des urines (pour bilharziose à <em>Schistosoma haematobium</em>), et le frottis sanguin (pour les filarioses).</li><li>D'autres examens spécifiques peuvent être réalisés : électrophorèse parasitologique des selles avec techniques de concentration (pour la strongyloïdose), imagerie (pour toxocarose, distomatose) et biopsie musculaire (pour la trichinellose).</li></ul>"},{"i":"16a29e673d31","n":218,"o":"218-4","u":"Diagnostic positif","t":"Connaître et savoir identifier les causes classiques d’éosinophilie (atopie, parasitoses, iatrogènes, cancer)","q":"Quels types de cancers peuvent être associés à une éosinophilie ?","a":"<p>Les cancers associés à une éosinophilie peuvent être des <strong>hémopathies</strong> (comme les <strong>lymphomes</strong> et les <strong>leucémies</strong>) ou des <strong>cancers solides</strong>. L'éosinophilie est alors souvent due à une production <strong>paranéoplasique d'IL-5</strong>.</p>"},{"i":"32983b2b041c","n":218,"o":"218-4","u":"Diagnostic positif","t":"Connaître et savoir identifier les causes classiques d’éosinophilie (atopie, parasitoses, iatrogènes, cancer)","q":"Quelle est la première approche diagnostique face à une éosinophilie, selon l'objectif EDN Rang A ?","a":"<p>Face à toute éosinophilie, il convient d'évoquer systématiquement quatre causes classiques, regroupées par le moyen mnémotechnique <strong>A.P.I.C.</strong> :</p><ul><li><strong>A</strong>topie</li><li><strong>P</strong>arasitoses</li><li><strong>I</strong>atrogène</li><li><strong>C</strong>ancer</li></ul>"},{"i":"93b4952109fe","n":218,"o":"218-4","u":"Diagnostic positif","t":"Connaître et savoir identifier les causes classiques d’éosinophilie (atopie, parasitoses, iatrogènes, cancer)","q":"Comment doit être envisagée une cause iatrogène face à une éosinophilie ?","a":"<p>La cause <strong>médicamenteuse</strong> doit être évoquée systématiquement. Il est important de rechercher un <strong>lien temporel</strong> avec l'introduction d'un traitement. Les manifestations peuvent aller d'un simple <strong>rash isolé</strong> au <strong>DRESS</strong> (Drug Reaction with Eosinophilia and Systemic Symptoms).</p>"},{"i":"98c3e369b209","n":218,"o":"218-4","u":"Diagnostic positif","t":"Connaître et savoir identifier les causes classiques d’éosinophilie (atopie, parasitoses, iatrogènes, cancer)","q":"Quels éléments orientent vers une éosinophilie d'origine atopique ?","a":"<p>Une éosinophilie d'origine atopique est suggérée par un <strong>terrain atopique</strong> comprenant <strong>asthme</strong>, <strong>rhinite</strong>, <strong>dermatite atopique</strong> ou <strong>urticaire</strong>. L'éosinophilie est généralement <strong>modérée</strong> (inférieure à <strong>1 G/L</strong>) et <strong>variable</strong> dans le temps.</p>"},{"i":"bd481c36c2a2","n":218,"o":"218-4","u":"Diagnostic positif","t":"Connaître et savoir identifier les causes classiques d’éosinophilie (atopie, parasitoses, iatrogènes, cancer)","q":"Quels sont les principaux types de parasitoses à rechercher en cas d'éosinophilie ?","a":"<p>Les parasitoses à rechercher sont principalement les <strong>helminthoses</strong>. La notion de <strong>voyage en zone tropicale</strong> est un élément d'orientation essentiel pour ces diagnostics.</p>"},{"i":"d5488e95df80","n":218,"o":"218-4","u":"Diagnostic positif","t":"Connaître et savoir identifier les causes classiques d’éosinophilie (atopie, parasitoses, iatrogènes, cancer)","q":"Selon l'objectif, quelles sont les trois causes les plus fréquentes d'hyperéosinophilie ?","a":"<p>Les trois causes les plus fréquentes d'hyperéosinophilie sont les <strong>dermatoses prurigineuses</strong>, les <strong>helminthiases</strong> et les <strong>allergies</strong>.</p>"},{"i":"0ee16c2d287e","n":218,"o":"218-9","u":"Identifier une urgence","t":"Identifier les situations d’urgence en présence d’une éosinophilie","q":"Quelles sont les étiologies graves d'éosinophilie nécessitant une prise en charge urgente ?","a":"<p>Les étiologies graves d'éosinophilie nécessitant une prise en charge urgente sont :</p><ul><li>L'<strong>atteinte cardiaque d'une GEPA</strong> (Granulomatose Éosinophilique avec Polyangéite).</li><li>Les <strong>hémopathies malignes</strong>.</li><li>L'<strong>anguillulose maligne</strong> (auto-réinfestation digestive chez l'immunodéprimé, surtout sous corticothérapie).</li><li>Le <strong>DRESS</strong> (Drug Rash with Eosinophilia and Systemic Symptoms).</li></ul>"},{"i":"23d161601051","n":218,"o":"218-9","u":"Identifier une urgence","t":"Identifier les situations d’urgence en présence d’une éosinophilie","q":"Quelles défaillances viscérales imposent une prise en charge en urgence en cas d'hyperéosinophilie ?","a":"<p>Les défaillances viscérales qui imposent une prise en charge en urgence sont :</p><ul><li>La <strong>défaillance respiratoire</strong>.</li><li>La <strong>défaillance cardiaque</strong>.</li><li>La <strong>défaillance neurologique</strong> (parfois d'origine thrombotique artérielle).</li></ul>"},{"i":"2a7dcc1db269","n":218,"o":"218-9","u":"Identifier une urgence","t":"Identifier les situations d’urgence en présence d’une éosinophilie","q":"Comment définit-on l'urgence face à une éosinophilie ?","a":"<p>L'urgence face à une éosinophilie se définit selon deux registres principaux : le <strong>retentissement viscéral</strong> de l'hyperéosinophilie et la présence de <strong>certaines étiologies graves</strong>.</p>"},{"i":"c197f76b2b5c","n":218,"o":"218-9","u":"Identifier une urgence","t":"Identifier les situations d’urgence en présence d’une éosinophilie","q":"Quelle conduite à tenir immédiate est requise devant une défaillance d'organe liée à une éosinophilie ?","a":"<p>Toute défaillance d'organe (respiratoire, cardiaque ou neurologique) liée à une éosinophilie impose une <strong>hospitalisation</strong> et un <strong>avis spécialisé</strong>. L'objectif est la prise en charge des fonctions vitales et la mise en œuvre d'un traitement étiologique ou présomptif.</p>"}]};